#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_dir_does_not_use_dot_bivvy() {
        let path = config_dir();
        assert!(
            !path.to_string_lossy().contains(".bivvy"),
            "config_dir should not use .bivvy: {:?}",
            path
        );
    }

    #[test]
    fn data_dir_does_not_use_dot_bivvy() {
        let path = data_dir();
        assert!(
            !path.to_string_lossy().contains(".bivvy"),
            "data_dir should not use .bivvy: {:?}",
