        );
    }

    #[test]
    fn config_dir_ends_with_bivvy() {
        let path = config_dir();
        assert!(
            path.ends_with("bivvy"),
            "config_dir should end with 'bivvy': {:?}",
            path
        );
    }

    #[test]
    fn data_dir_ends_with_bivvy() {
        let path = data_dir();
        assert!(
            path.ends_with("bivvy"),
            "data_dir should end with 'bivvy': {:?}",
            path
        );
    }

    #[test]
    fn config_dir_uses_platform_config_location() {
        let path = config_dir();
        if let Some(expected_base) = dirs::config_dir() {
            assert_eq!(path, expected_base.join("bivvy"));
        }
    }

    #[test]
    fn data_dir_uses_platform_data_location() {
        let path = data_dir();
        if let Some(expected_base) = dirs::data_local_dir() {
            assert_eq!(path, expected_base.join("bivvy"));
        }
    }
}

