/// Returns the platform-standard configuration directory for Bivvy.
///
/// Uses `dirs::config_dir()` to respect XDG conventions:
/// - Linux: `$XDG_CONFIG_HOME/bivvy` or `~/.config/bivvy`
/// - macOS: `~/Library/Application Support/bivvy`
/// - Windows: `{FOLDERID_RoamingAppData}\bivvy`
pub fn config_dir() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("bivvy")
}

/// Returns the platform-standard data directory for Bivvy.
///
/// Uses `dirs::data_local_dir()` to respect XDG conventions:
/// - Linux: `$XDG_DATA_HOME/bivvy` or `~/.local/share/bivvy`
/// - macOS: `~/Library/Application Support/bivvy`
/// - Windows: `{FOLDERID_LocalAppData}\bivvy`
pub fn data_dir() -> PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("bivvy")
}

